alter table maintenance_work_orders drop constraint if exists maintenance_work_orders_status_check;
alter table maintenance_work_orders add column if not exists request_type text;
alter table maintenance_work_orders add column if not exists maintenance_requested_at timestamptz;
alter table maintenance_work_orders add column if not exists counts_as_downtime boolean not null default false;
alter table maintenance_work_orders add column if not exists operator_request_key text;
alter table maintenance_work_orders add constraint maintenance_work_orders_status_check check(status in('open','in_progress','waiting_parts','waiting_external','completed','cancelled','OPEN_OPERATOR','WAITING_MAINTENANCE','REQUESTED'));
create unique index if not exists maintenance_operator_request_key_uq on maintenance_work_orders(organization_id,operator_request_key) where operator_request_key is not null;
create or replace function maintenance_operator_start_request(p_organization_id uuid,p_asset_id uuid,p_request_type text,p_request_key text,p_actor_id uuid,p_actor_email text)returns uuid language plpgsql security definer set search_path=public as $$declare w uuid;n text;s text;stopped boolean;begin if p_request_type not in('OPERATOR_FIX','CORRECTIVE_NOW','SCHEDULE_CORRECTIVE')then raise exception'Invalid request type';end if;perform pg_advisory_xact_lock(hashtext(p_asset_id::text));select id into w from maintenance_work_orders where organization_id=p_organization_id and operator_request_key=p_request_key limit 1;if w is not null then return w;end if;stopped:=p_request_type in('OPERATOR_FIX','CORRECTIVE_NOW');if stopped then select work_order_id into w from maintenance_downtime_events where organization_id=p_organization_id and asset_id=p_asset_id and ended_at is null order by started_at limit 1;if w is not null then return w;end if;end if;if not exists(select 1 from maintenance_assets where id=p_asset_id and organization_id=p_organization_id and active)then raise exception'Invalid asset';end if;s:=case p_request_type when'OPERATOR_FIX'then'OPEN_OPERATOR'when'CORRECTIVE_NOW'then'WAITING_MAINTENANCE'else'REQUESTED'end;n:='WO-'||extract(year from now()at time zone'Australia/Brisbane')::int||'-'||lpad(nextval('maintenance_work_order_seq')::text,6,'0');insert into maintenance_work_orders(organization_id,work_order_number,asset_id,status,priority,title,requested_by,requested_by_email,request_type,maintenance_requested_at,counts_as_downtime,operator_request_key)values(p_organization_id,n,p_asset_id,s,case when p_request_type='CORRECTIVE_NOW'then'critical'when p_request_type='OPERATOR_FIX'then'high'else'medium'end,replace(p_request_type,'_',' '),p_actor_id,p_actor_email,p_request_type,case when p_request_type='CORRECTIVE_NOW'then now()end,stopped,p_request_key)returning id into w;insert into maintenance_work_order_history(organization_id,work_order_id,from_status,to_status,changed_by,changed_by_email)values(p_organization_id,w,null,s,p_actor_id,p_actor_email);if stopped then insert into maintenance_downtime_events(organization_id,asset_id,host_asset_id,work_order_id,reason,started_by,maintenance_class,counts_as_failure,counts_as_downtime)values(p_organization_id,p_asset_id,p_asset_id,w,replace(p_request_type,'_',' '),p_actor_id,'CORRECTIVE',true,true);update maintenance_assets set status='down',updated_at=now()where id=p_asset_id;end if;return w;end$$;
create or replace function maintenance_operator_classify(p_organization_id uuid,p_work_order_id uuid,p_problem_area text,p_symptom text,p_comment text,p_actor_id uuid,p_actor_email text)returns void language plpgsql security definer set search_path=public as $$begin update maintenance_work_orders set problem_description=concat_ws(' · ',nullif(trim(p_problem_area),''),nullif(trim(p_symptom),''),nullif(trim(p_comment),'')),updated_at=now()where id=p_work_order_id and organization_id=p_organization_id;if not found then raise exception'Work order not found';end if;insert into maintenance_work_order_comments(organization_id,work_order_id,user_id,author_email,comment)select p_organization_id,p_work_order_id,p_actor_id,p_actor_email,concat('Operator classification: ',concat_ws(' · ',nullif(trim(p_problem_area),''),nullif(trim(p_symptom),''),nullif(trim(p_comment),'')))where coalesce(trim(p_problem_area),'')<>''or coalesce(trim(p_symptom),'')<>''or coalesce(trim(p_comment),'')<>'';end$$;
create or replace function maintenance_operator_escalate(p_organization_id uuid,p_work_order_id uuid,p_actor_id uuid,p_actor_email text)returns void language plpgsql security definer set search_path=public as $$declare old text;begin select status into old from maintenance_work_orders where id=p_work_order_id and organization_id=p_organization_id for update;if old is null then raise exception'Work order not found';end if;if old='OPEN_OPERATOR'then update maintenance_work_orders set status='WAITING_MAINTENANCE',request_type='CORRECTIVE_NOW',maintenance_requested_at=coalesce(maintenance_requested_at,now()),updated_at=now()where id=p_work_order_id;insert into maintenance_work_order_history(organization_id,work_order_id,from_status,to_status,changed_by,changed_by_email)values(p_organization_id,p_work_order_id,old,'WAITING_MAINTENANCE',p_actor_id,p_actor_email);end if;end$$;
create or replace function maintenance_operator_resolve(p_organization_id uuid,p_work_order_id uuid,p_actor_id uuid,p_actor_email text)returns void language plpgsql security definer set search_path=public as $$declare old text;a uuid;begin select status,asset_id into old,a from maintenance_work_orders where id=p_work_order_id and organization_id=p_organization_id for update;if old is null then raise exception'Work order not found';end if;if old='OPEN_OPERATOR'then update maintenance_work_orders set status='completed',resolution='Resolved by operator',completed_at=now(),updated_at=now()where id=p_work_order_id;update maintenance_downtime_events set ended_at=now(),ended_by=p_actor_id where work_order_id=p_work_order_id and ended_at is null;update maintenance_assets set status='operational',updated_at=now()where id=a and not exists(select 1 from maintenance_downtime_events where asset_id=a and ended_at is null);insert into maintenance_work_order_history(organization_id,work_order_id,from_status,to_status,changed_by,changed_by_email)values(p_organization_id,p_work_order_id,old,'completed',p_actor_id,p_actor_email);end if;end$$;
revoke all on function maintenance_operator_start_request(uuid,uuid,text,text,uuid,text),maintenance_operator_classify(uuid,uuid,text,text,text,uuid,text),maintenance_operator_escalate(uuid,uuid,uuid,text),maintenance_operator_resolve(uuid,uuid,uuid,text)from public,anon,authenticated;
grant execute on function maintenance_operator_start_request(uuid,uuid,text,text,uuid,text),maintenance_operator_classify(uuid,uuid,text,text,text,uuid,text),maintenance_operator_escalate(uuid,uuid,uuid,text),maintenance_operator_resolve(uuid,uuid,uuid,text)to service_role;
